/**
 * Which files outside the plan SFlow settles, and which go to a person [owner, 2026-11-19, C3]. An allowlist: companion,
 * test support (page objects by the repository's own test configuration or by their content, never by name), documentation,
 * ignore files and generated files whose source is planned. Everything else is a person's question, each class in its own
 * words, and the vetoes hold even inside an allowed class. The earlier draft (cut3) settled lock files, package.json, CI,
 * Dockerfiles, CODEOWNERS and any file under the step's only row; none of those is settled here.
 */
import assert from 'node:assert/strict';
import test from 'node:test';

import { outOfPlanPlace, personClass, SENSITIVE_PATH_PATTERNS } from '../src/out-of-plan-classes.mjs';
import { DEFAULT_QUICK_FIX_POLICY } from '../src/quick-fix-policy.mjs';
import { contentTestSupport, importNames, libraryOf } from '../src/test-support-detection.mjs';
import { runnerTestRoots } from '../src/test-collection-limits.mjs';
import { classificationContext, recordPlanAmendment, settledPlanChanges } from '../src/plan-amendments.mjs';
import { classifySupportingChange } from '../src/supporting-changes.mjs';
import { isTestAutomationPath, isTestSupportPath } from '../src/source-boundary.mjs';
import { plannedSupportingFiles } from '../src/specifications.mjs';

const plan = {
  'OOP-1:AC-001': { expectedPaths: ['src/Pricing.tsx', 'src/api.proto'], steps: ['implement'] },
  'OOP-1:AC-002': { expectedPaths: [], tests: ['tests/pricing.spec.ts'], fulfillment: 'test-only', steps: ['implement'] }
};
const place = (file, extra = {}) => outOfPlanPlace(file, { plan, phaseId: 'implement', ...extra });
const settled = (file, extra) => place(file, extra).settle?.class ?? null;
const asked = (file, extra) => place(file, extra).person?.class ?? null;

test('the settle classes: companion, test support by path, documentation, ignore files, and a generated file whose source is planned', () => {
  assert.equal(settled('src/Pricing.module.css'), 'companion');
  assert.deepEqual(place('src/Pricing.module.css').settle.effect, { clauseId: 'OOP-1:AC-001', path: 'src/Pricing.module.css' });
  assert.equal(settled('tests/support/login-helper.ts'), 'test-support');
  assert.equal(settled('conftest.py'), 'test-support');
  assert.deepEqual(place('conftest.py').settle.effect, { file: 'conftest.py', class: 'test-support' });
  assert.equal(settled('README.md'), 'documentation');
  assert.equal(settled('docs/pricing.md'), 'documentation');
  assert.equal(settled('.gitignore'), 'ignore-file');
  assert.deepEqual(place('.gitignore').settle.effect, { file: '.gitignore', class: 'repository-metadata' });
  // Generated: its first lines say so, and its source beside it is planned.
  const head = () => '// Code generated by protoc-gen-ts. DO NOT EDIT.\nexport const x = 1;\n';
  assert.equal(settled('src/api.pb.ts', { head, settledRows: new Map([['src/api.proto', 'OOP-1:AC-001']]) }), 'companion', 'a companion first');
  assert.equal(settled('gen/api.pb.ts', { head, settledRows: new Map([['gen/api.proto', 'OOP-1:AC-001']]) }), 'generated');
  assert.equal(asked('gen/api.pb.ts', { head: () => 'export const x = 1;\n', settledRows: new Map([['gen/api.proto', 'OOP-1:AC-001']]) }), 'behaviour', 'no marker, a person');
  assert.equal(asked('gen/other.pb.ts', { head, settledRows: new Map() }), 'behaviour', 'no source planned, a person');
  // The agent's own words, when it recorded the file, are one more line of evidence.
  assert.match(JSON.stringify(place('README.md', { reason: 'The readme says how to run the export.' }).settle.evidence), /the agent says: The readme says how to run the export\./u);
});

test('never settled: a dependency, build, CI or runner configuration, governance metadata, or anything that can change behaviour', () => {
  for (const file of ['package.json', 'package-lock.json', 'yarn.lock', 'requirements.txt', 'pyproject.toml', 'go.mod', 'Cargo.toml', 'pom.xml', 'build.gradle', 'Gemfile', 'app/App.csproj']) {
    assert.equal(asked(file), 'dependency', file);
  }
  for (const file of ['jest.config.js', 'vitest.config.ts', 'playwright.config.ts', 'cypress.config.ts', 'tsconfig.json', '.github/workflows/ci.yml', '.github/actions/setup/run.sh', 'Makefile']) {
    assert.equal(asked(file), 'build', file);
  }
  for (const file of ['CODEOWNERS', '.gitattributes', '.github/dependabot.yml', 'renovate.json', '.github/pull_request_template.md', '.vscode/tasks.json']) {
    assert.equal(asked(file), 'governance', file);
  }
  // The step's only row is a recommendation, never a settlement: application code is a person's.
  assert.equal(asked('src/extra.mjs'), 'behaviour');
  assert.match(place('src/extra.mjs').person.words, /can change what the product does/u);
  assert.match(personClass('package.json').words, /third-party code/u);
});

test('the vetoes hold inside an allowed class', () => {
  for (const file of ['Dockerfile', 'auth/README.md', 'docs/api/README.md', 'infra/README.md', 'src/security/Pricing.module.css', 'db/migrations/README.md']) {
    assert.equal(asked(file), 'sensitive', file);
  }
  assert.equal(asked('config/settings.json'), 'sensitive', 'runtime configuration');
  assert.equal(asked('.env.example'), 'sensitive');
  assert.equal(asked('docs/guide.md', { protectedPaths: ['docs/'] }), 'sensitive', 'a protected path');
  assert.equal(asked('README.md', { rejected: new Set(['README.md']) }), 'sensitive', 'a person rejected it');
  assert.equal(asked('README.md', { undone: new Set(['README.md']) }), 'sensitive', 'a person undid it');
  assert.equal(asked('README.md', { open: new Set(['README.md']) }), 'sensitive', 'it already waits as a departure');
  // The quick-fix policy's patterns are all here, with infra.
  assert.deepEqual(DEFAULT_QUICK_FIX_POLICY.prohibitedPathPatterns.map((pattern) => pattern.source.replace('infrastructure|', 'infrastructure|infra|')),
    SENSITIVE_PATH_PATTERNS.map((pattern) => pattern.source));
});

test('page objects: the repository\'s test configuration names their folder, unless this Story changed it', () => {
  const read = (file) => ({ 'playwright.config.ts': "export default defineConfig({ testDir: './e2e' });", 'qa/playwright.config.ts': 'export default {};' }[file] ?? null);
  const roots = runnerTestRoots(['playwright.config.ts', 'qa/playwright.config.ts'], read);
  assert.deepEqual(roots.map((entry) => entry.root), ['e2e', 'qa']);
  const testSupport = new Map([['qa/pages/QuestionnairePage.ts', { rule: 'test-root', evidence: [{ what: roots[1].words, where: roots[1].config }] }]]);
  const page = place('qa/pages/QuestionnairePage.ts', { testSupport });
  assert.equal(page.settle.class, 'test-support');
  assert.deepEqual(page.settle.effect, { file: 'qa/pages/QuestionnairePage.ts', class: 'test-support', rule: 'test-root' });
  // Its name alone never settles it: src/pages/HomePage.tsx is product code.
  assert.equal(asked('src/pages/HomePage.tsx'), 'behaviour');
  assert.equal(asked('pages/QuestionnairePage.ts'), 'behaviour');
});

test('page objects: content and importers settle the office case, interface included; a product importer, a production dependency or a changed manifest does not', () => {
  const page = "import { Page } from '@playwright/test';\nimport { IQuestionnairePage } from './IQuestionnairePage';\nexport class QuestionnairePage implements IQuestionnairePage { constructor(readonly page: Page) {} }\n";
  const contract = 'export interface IQuestionnairePage { open(): Promise<void>; }\n';
  const spec = "import { test } from '@playwright/test';\nimport { QuestionnairePage } from '../pages/QuestionnairePage';\nimport type { IQuestionnairePage } from '../pages/IQuestionnairePage';\ntest('q', async () => {});\n";
  const texts = new Map([['pages/QuestionnairePage.ts', page], ['pages/IQuestionnairePage.ts', contract], ['tests/questionnaire.spec.ts', spec]]);
  const candidates = ['pages/QuestionnairePage.ts', 'pages/IQuestionnairePage.ts'];
  const isTest = (file) => isTestAutomationPath(file);
  const dev = () => ({ ok: true, words: '@playwright/test is a devDependency of package.json, unchanged by this Story' });
  const found = contentTestSupport(candidates, { texts, isTest, devDependency: dev });
  assert.deepEqual([...found.keys()].sort(), candidates.slice().sort());
  assert.match(JSON.stringify(found.get('pages/QuestionnairePage.ts').evidence), /imports @playwright\/test \(line 1\)/u);
  assert.match(JSON.stringify(found.get('pages/QuestionnairePage.ts').evidence), /only tests and other test support use it: tests\/questionnaire\.spec\.ts/u);
  // Settled with its evidence, then every reader agrees it is test support while the settlement stands.
  const workflow = { settledDecisions: [{ id: 'STL-001', kind: 'plan-accounting', subject: 'file:pages/QuestionnairePage.ts', answer: 'Listed it.', effect: { file: 'pages/QuestionnairePage.ts', class: 'test-support', rule: 'test-content' } }] };
  const context = classificationContext(workflow);
  assert.equal(classifySupportingChange('pages/QuestionnairePage.ts', context).class, 'test-support');
  assert.equal(isTestSupportPath('pages/QuestionnairePage.ts', context), true);
  assert.equal(isTestAutomationPath('pages/QuestionnairePage.ts', context), true, 'a test-only row may take it');
  assert.deepEqual(plannedSupportingFiles([{ supportingFiles: ['pages/QuestionnairePage.ts'] }], context), ['pages/QuestionnairePage.ts']);
  assert.deepEqual(settledPlanChanges(workflow).map((change) => [change.kind, change.path, change.class]), [['add-supporting', 'pages/QuestionnairePage.ts', 'test-support']]);
  const amended = { ...workflow, workItem: { id: 'OOP-1' } };
  assert.equal(recordPlanAmendment(amended, { changes: [{ kind: 'add-location', clauseId: 'OOP-1:AC-002', path: 'pages/QuestionnairePage.ts' }], reason: 'The page object serves the questionnaire test.',
    actor: 'a', authorityGroup: 'g', at: '2026-11-19T09:00:00.000Z', plan }).changes[0].path, 'pages/QuestionnairePage.ts', 'a test-only row takes settled test support');
  // Undone, it is product code by its path again, everywhere.
  const undone = { settledDecisions: [...workflow.settledDecisions, { id: 'STL-002', undoes: 'STL-001' }] };
  assert.equal(classificationContext(undone), null);
  assert.equal(classifySupportingChange('pages/QuestionnairePage.ts', classificationContext(undone)).refused, 'application-source');
  // A product file imports it: a person.
  const product = new Map([...texts, ['src/app.ts', "import { QuestionnairePage } from '../pages/QuestionnairePage';\n"]]);
  assert.deepEqual([...contentTestSupport(candidates, { texts: product, isTest, devDependency: dev }).keys()], []);
  // The library is a production dependency, or the Story changed package.json: a person.
  assert.deepEqual([...contentTestSupport(candidates, { texts, isTest, devDependency: () => ({ ok: false }) }).keys()], []);
  // A React page with no test library and no importer that is a test: a person.
  assert.deepEqual([...contentTestSupport(['src/pages/HomePage.tsx'], { texts: new Map([['src/pages/HomePage.tsx', 'export default function Home() { return null; }\n']]), isTest, devDependency: dev }).keys()], []);
  assert.equal(libraryOf('@wdio/globals'), '@wdio/globals');
  assert.equal(importNames('tests/a.spec.ts', '../pages/QuestionnairePage', 'pages/QuestionnairePage.ts'), true);
  assert.equal(importNames('tests/test_q.py', 'pages.questionnaire_page', 'qa/pages/questionnaire_page.py'), true);
});

test('undo of a settled file: refused while its step awaits approval, with the filled return route; closed once approved', async () => {
  const { undoSettledDecision } = await import('../src/settled-decisions.mjs');
  const { settledLedger } = await import('../src/decision-list.mjs');
  const workflow = (status) => ({ workItem: { id: 'OOP-1' }, currentPhase: 'implement', phaseOrder: ['implement'],
    phases: { implement: { id: 'implement', label: 'Implementation', status } },
    settledDecisions: [{ id: 'STL-001', kind: 'plan-accounting', by: 'sflow', phase: 'implement', subject: 'file:README.md', answer: 'Listed README.md in the plan as a supporting change (documentation).',
      evidence: [{ what: 'README.md is documentation', where: 'the repository root' }], effect: { file: 'README.md', class: 'documentation' }, at: '2026-11-19T09:00:00.000Z' }] });
  await assert.rejects(undoSettledDecision('/nonexistent', {}, workflow('awaiting_approval'), 'STL-001', { actor: { name: 'a' } }), (error) => {
    assert.equal(error.code, 'SETTLED_DECISION_DURING_REVIEW');
    assert.equal(error.details.nextAction.command, 'singularity-flow reject implement --work-id OOP-1 --fetch --to implement --reason <reason>');
    assert.equal(error.details.nextAction.skill, '/sf-reject');
    return true;
  });
  await assert.rejects(undoSettledDecision('/nonexistent', {}, workflow('approved'), 'STL-001', { actor: { name: 'a' } }), { code: 'SETTLED_DECISION_CLOSED' });
  // What the delivered code's approval lists, one line per group, each settlement with its own undo.
  const [group] = settledLedger(workflow('awaiting_approval'), 'implement');
  assert.equal(group.words, '1 documentation file listed as a supporting change');
  assert.equal(group.settled[0].undo, 'singularity-flow decisions undo OOP-1 --settled STL-001');
});
